steps.analogousExample:
/* Example: button with hover effect and will-change */
button {
  background-color: #3498db;
  color: white;
  padding: 12px 24px;
  border: none;
  border-radius: 6px;
  font-size: 16px;
  transition: transform 0.3s, background-color 0.3s;
  will-change: transform;
}

button:hover {
  background-color: #2980b9;
  transform: scale(1.05);
}

